// Executed only inside the isolated Chromium fixture generated by measureFirebaseBrowser.cjs.
import React from 'react';
import { createRoot } from 'react-dom/client';
import { MemoryRouter } from 'react-router-dom';
import { ChakraProvider } from '@chakra-ui/react';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from './src/firebaseConfig';
import './src/i18n/index.js';
import Coach from './src/components/CoachDashboard';
import Clients from './src/components/Clients';
import './src/utils/firestoreMetrics';
import { onClub } from './clubBubble';
import DashboardMessagingBubble from './src/components/messaging/DashboardMessagingBubble';
import useClubUnreadCount from './src/components/messaging/useClubUnreadCount';
import { useAuth } from './src/AuthContext';

const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
const result = {};
const publish = data => fetch('/fixture-results', { method: 'POST', body: JSON.stringify(data) });

async function sample(name, Page, route, warm, run = 1) {
  await fetch('/fixture-start');
  window.bylFirestoreMetrics.reset();
  const mounted = performance.now();
  const root = createRoot(document.getElementById('root'));
  root.render(<ChakraProvider><MemoryRouter initialEntries={[route]}><Page /></MemoryRouter></ChakraProvider>);
  const selector = name === 'coach' ? 'coach-dashboard-timing' : 'page-loading-timing';
  try {
    let state;
    while (performance.now() - mounted < 35000) {
      await wait(100);
      state = JSON.parse(document.querySelector('[data-testid="' + selector + '"]')?.textContent || '{}');
      if ((state.core?.status || state.status) === 'ready') break;
      if ((state.core?.status || state.status) === 'error') throw Error(name + '-load-error');
    }
    if ((state?.core?.status || state?.status) !== 'ready') {window.fixtureDiagnostic={state,metrics:window.bylFirestoreMetrics.snapshot()};throw Error(name + '-timeout');}
    const coreReadyMs = Math.round(performance.now() - mounted);
    await wait(500);
    result[name + (warm ? '-warm' : '-cold') + (run === 1 ? '' : '-' + run)] = { coreReadyMs,
      viewportWidth: window.innerWidth, cacheSeen: !!(state.coreCache || state.hasCache),
      cacheMarkMs: state.coreCache?.mountMs || state.cache?.mountMs || null, http: await (await fetch('/fixture-stop')).json(), ...window.bylFirestoreMetrics.snapshot() };
    if (name === 'coach' && warm && run === 1) {
      await fetch('/fixture-start');
      window.bylFirestoreMetrics.reset();
      await wait(62000);
      result['coach-idle-62s'] = { http: await (await fetch('/fixture-stop')).json(), ...window.bylFirestoreMetrics.snapshot() };
      await fetch('/fixture-start');
      window.bylFirestoreMetrics.reset();
      const change = await fetch('/fixture-calendar-change', { method: 'POST' });
      if (!change.ok) throw Error('calendar-fixture');
      await wait(3200);
      result['coach-calendar-change'] = { http: await (await fetch('/fixture-stop')).json(), ...window.bylFirestoreMetrics.snapshot() };
    }
  } finally {
    root.unmount();
    await wait(350);
  }
}

async function signInOwner() {
  const owner = await (await fetch('/fixture-owner')).json();
  await signInWithEmailAndPassword(auth, owner.email, owner.password);
  window.fixtureOwner = true;
}

function ClubBadgeAndBubble() {
  const { user } = useAuth();
  useClubUnreadCount('sample');
    return onClub(user, { pathname: '/club-dashboard' }) ? <DashboardMessagingBubble notificationsOnly /> : null;
}

function renderBadge() {
  const root = createRoot(document.getElementById('root'));
  root.render(<ChakraProvider><MemoryRouter initialEntries={['/club-dashboard']}><ClubBadgeAndBubble /></MemoryRouter></ChakraProvider>);
  return root;
}

async function samplePeer() {
  await signInOwner();
  renderBadge();
  window.opener.postMessage('lot1-peer-ready', location.origin);
}

async function sampleTwoTabs() {
  const peerReady = new Promise((resolve, reject) => {
    const timeout = setTimeout(() => { window.removeEventListener('message', onMessage); reject(Error('peer-timeout')); }, 20000);
    function onMessage(event) {
      if (event.origin !== location.origin || event.data !== 'lot1-peer-ready') return;
      clearTimeout(timeout);
      window.removeEventListener('message', onMessage);
      resolve();
    }
    window.addEventListener('message', onMessage);
  });
  const peer = window.open('/?peer', '_blank');
  try {
    await peerReady;
    await fetch('/fixture-start');
    await wait(22000);
    result['club-two-tabs-22s'] = { http: await (await fetch('/fixture-stop')).json() };
  } finally { peer?.close(); }
}

async function sampleAdmin() {
  const { default: AdminGeo } = await import('./src/pages/AdminGeo');
  const admin = await (await fetch('/fixture-administrator')).json();
  await signInWithEmailAndPassword(auth, admin.email, admin.password);
  window.fixtureAdmin = true;
  const root = createRoot(document.getElementById('root'));
  await fetch('/fixture-start');
  window.bylFirestoreMetrics.reset();
  root.render(<ChakraProvider><MemoryRouter initialEntries={['/admin/geo']}><AdminGeo /></MemoryRouter></ChakraProvider>);
  await wait(17000);
  result['admin-geo-17s'] = { http: await (await fetch('/fixture-stop')).json(), ...window.bylFirestoreMetrics.snapshot() };
  root.unmount();
}

(async () => {
  if (location.search === '?peer') return samplePeer();
  const account = await (await fetch('/fixture-coach')).json();
  await signInWithEmailAndPassword(auth, account.email, account.password);
  for (const warm of [false, true]) {
    await sample('clients', Clients, '/clients?pagePerf', warm);
    await sample('coach', Coach, '/coach-dashboard?dashboardPerf', warm);
  }
  if (globalThis.fixtureExtended) for (let run = 2; run <= 5; run++) {
    await sample('clients', Clients, '/clients?pagePerf', true, run);
    await sample('coach', Coach, '/coach-dashboard?dashboardPerf', true, run);
  }
  await signInOwner();
  await fetch('/fixture-start');
  window.bylFirestoreMetrics.reset();
  const root = renderBadge();
  await wait(22000);
  result['club-badge-22s'] = { http: await (await fetch('/fixture-stop')).json(), ...window.bylFirestoreMetrics.snapshot() };
  if (globalThis.fixtureExtended) await sampleTwoTabs();
  root.unmount();
  if (globalThis.fixtureExtended) await sampleAdmin();
  await publish(result);
})().catch(error => publish({diagnostic:window.fixtureDiagnostic,failure: /^(clients|coach)-(load-error|timeout)$/.test(error.message) ? error.message : 'browser-error'}));
